function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*1299709+3);var n=24,q=0,c=0,tQ=0,tC=0;for(var i=0;i<n;i++){var size=4+((R()*60)|0),st=R();var score=size/64*0.7+st*0.3;var tc=size*size/100;if(score>0.55&&size>=16){q++;tQ+=tc/8+0.5;}else{c++;tC+=tc;}}var R2=prng(seed*1299709+3),allC=0;for(var j=0;j<n;j++){var s2=4+((R2()*60)|0);allC+=s2*s2/100;}var hybrid=tQ+tC;return{subtasks:n,routed_quantum:q,routed_classical:c,hybrid_cost:+hybrid.toFixed(2),all_classical_cost:+allC.toFixed(2),speedup_vs_classical:+(allC/hybrid).toFixed(2)};}
var SEED = 78501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

